@sig trait Inventory_Assessment_Api {
  def id: Art.BridgeId
  def pending_request_Id : Art.PortId
  def inventory_evidence_Id : Art.PortId
  def inventory_finding_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var inventory_finding: Factory_Dispatch_Coordinator.Inventory_Finding.Type = $

  def put_inventory_finding(value : Factory_Dispatch_Coordinator.Inventory_Finding.Type) : Unit = {
    Contract(
      Modifies(inventory_finding),
      Ensures(
        inventory_finding == value
      )
    )
    Spec {
      inventory_finding = value
    }

    Art.putValue(inventory_finding_Id, Factory_Dispatch_Coordinator.Inventory_Finding_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Inventory_Assessment_Initialization_Api (
  val id: Art.BridgeId,
  val pending_request_Id : Art.PortId,
  val inventory_evidence_Id : Art.PortId,
  val inventory_finding_Id : Art.PortId) extends Inventory_Assessment_Api

